757	        float denom = 0.0f;
758	        #pragma unroll
759	        for (int kj = 0; kj < dec::kSeq; ++kj) {
760	            float e = (kj <= qi) ? __expf(sc[kj] - maxs) : 0.0f; sc[kj] = e; denom += e;
761	        }
762	        float invd = 1.0f / denom;
763	        float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq + qi) * dec::kSeq;
764	        #pragma unroll
765	        for (int kj = 0; kj < dec::kSeq; ++kj) aw[kj] = sc[kj] * invd;
766	        #pragma unroll
767	        for (int t = 0; t < dec::kDhead; ++t) {
768	            float acc = 0.0f;
769	            #pragma unroll
770	            for (int kj = 0; kj <= qi; ++kj) {
771	                float vv = __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t]);
772	                acc += aw[kj] * vv;
773	            }
774	            ctx[(int64_t)(rbase + qi) * dec::kD + qoff + t] = acc;
775	        }
776	    }
777	    __syncthreads();
778	}
