780	// Global SAMPLE index of the si-th sample in a tile whose first token row is g0.
781	__device__ __forceinline__ int si_global(int g0, int si) { return g0 / dec::kSeq + si; }
782	
783	// ════════════════════════════════════════════════════════════════════════
784	//  FORWARD over one TOKEN TILE (nrows = nsamp samples × kSeq positions), global
785	//  token rows [g0, g0+nrows). Tile-batched: the four per-layer linears
786	//  (in_proj/out_proj/ff0/ff2) run on wgmma (M=nrows, N-tiled); attention/LN/
787	//  GELU are scalar fp32 over the tile; head/CE are scalar per-sample (M=nsamp<
788	//  64). Writes the DecActs X-inputs (bf16 dW operands), the per-CTA tile scratch
789	//  (qkv/ff0pre/attn/LN caches/x1/finalin/logits the bwd needs), and returns the
790	//  tile's summed NLL (thread 0 holds it). `tok_ids`/`tgt_ids` are HBM int32.
791	//
792	//  DATAFLOW (DecActs X-regions = bf16 dW operands AND inter-stage operands;
793	//  dedicated fp32 scratch for residuals/LN; weights convert fp32→bf16 on read):
794	//    X_in[li]  := layer input (bf16)           [embedding for li=0]
795	//    qkv(bf16) := X_in @ in_w^T + in_b   (in_b folded fp32 → re-round bf16)
796	//    ctx       := attn(qkv) → X_ctx[li] (bf16, out_proj input + dW operand)
797	//    a(work)   := X_ctx @ out_w^T ; r1=X_in+a+out_b (work); n1(r1)→x1(fp32)→X_x1[li]
798	//    ff0(work) := X_x1 @ ff0_w^T ; (ff0+ff0_b)→ff0pre(bf16); gelu(ff0+ff0_b)→X_gact[li](bf16)
799	//    ff2(work) := X_gact @ ff2_w^T ; r2=x1+ff2+ff2_b (work); n2(r2)→X_in[li+1]
800	//                 (last layer: n2→finalin fp32, the head input)
801	//  BIASES (in/out/ff0/ff2) are folded in fp32 at these points (the oracle adds
802	//  them in fp32 after the bf16 matmul); LN β + head out_b were already applied.
803	// ════════════════════════════════════════════════════════════════════════
804	__device__ float dectc_forward_tile(
805	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, const DecActs& acts,
806	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
807	        const int* __restrict__ tgt_ids,
808	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
809	    const int nsamp = nrows / dec::kSeq;
810	    // ── Embedding: X_in[0][r] = tok[token_id[g0+r]] + pos[(g0+r)%S]. bf16. ──
811	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
812	        const int r = idx / dec::kD, j = idx % dec::kD;
813	        const int g = g0 + r;
814	        const int tid = tok_ids[g];
815	        const int sp = g % dec::kSeq;            // position within the sample
816	        float v = w.tok[(int64_t)tid * dec::kD + j] + w.pos[(int64_t)sp * dec::kD + j];
817	        acts.X_in[0][(int64_t)g * dec::kD + j] = __float2bfloat16(v);
818	    }
819	    __syncthreads();
820	
821	    for (int li = 0; li < dec::kLayers; ++li) {
822	        const DecWeights::Layer& L = w.layer[li];
823	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
824	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
825	        dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, wb.in_w[li], sc.qkv[li], dec::kD, 3 * dec::kD, sA, sB);
826	        __syncthreads();
827	        // add in_b (the fwd GEMM did W only; bias folded in scalar here for qkv —
828	        // matches the bf16-faithful oracle qkv = bf(x_in @ bf(in_w)^T + in_b)).
829	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x) {
830	            const int j = idx % (3 * dec::kD);
831	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
832	            sc.qkv[li][idx] = __float2bfloat16(v);
833	        }
834	        __syncthreads();
835	        // attention → ctx (work fp32) + attn[li] weights.
836	        dectc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
837	        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
838	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
839	            const int r = idx / dec::kD, j = idx % dec::kD;
840	            acts.X_ctx[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.work[(int64_t)r * dec::kD + j]);
841	        }
842	        __syncthreads();
843	        // a = X_ctx @ out_w^T (+ out_b)  (N=d, K=d). fp32 → work.
844	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * dec::kD, wb.out_w[li],
845	                                            sc.work, dec::kD, dec::kD, sA, sB);
846	        __syncthreads();
847	        // r1 = Xin + a + out_b → work (fp32). out_b folded here (the GEMM did W only)
848	        // — matches the oracle a = ctx_b @ out_w^T + out_b kept fp32 through r1.
849	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
850	            const int r = idx / dec::kD, j = idx % dec::kD;
851	            sc.work[(int64_t)r * dec::kD + j] += __bfloat162float(Xin[(int64_t)r * dec::kD + j]) + L.out_b[j];
852	        }
853	        __syncthreads();
854	        // n1(r1) → x1 (fp32) + caches[li]; then bf16 → X_x1[li] (ff0 input + dW operand).
855	        dectc_ln_fwd_tile(sc.work, L.n1_w, L.n1_b, nrows, sc.x1, sc.n1x[li], sc.n1i[li], red);
856	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
857	            const int r = idx / dec::kD, j = idx % dec::kD;
858	            acts.X_x1[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.x1[(int64_t)r * dec::kD + j]);
859	        }
860	        __syncthreads();
861	        // ff0 = X_x1 @ ff0_w^T (+ ff0_b)  (N=dff, K=d). fp32 → work; (pre+b) bf16 →
862	        // ff0pre; gelu(pre+b) → X_gact[li] (bf16, ff2 input + dW operand). ff0_b folded
863	        // into pre (fp32) — matches the oracle ff0pre=bf(ff0+b), gact=bf(gelu(ff0+b)).
864	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_x1[li] + (int64_t)g0 * dec::kD, wb.ff0_w[li],
865	                                            sc.work, dec::kD, dec::kDff, sA, sB);
866	        __syncthreads();
867	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
868	            const int r = idx / dec::kDff, j = idx % dec::kDff;
869	            float pre = sc.work[(int64_t)r * dec::kDff + j] + L.ff0_b[j];
870	            sc.ff0pre[li][(int64_t)r * dec::kDff + j] = __float2bfloat16(pre);
871	            acts.X_gact[li][(int64_t)(g0 + r) * dec::kDff + j] = __float2bfloat16(dec_gelu(pre));
872	        }
873	        __syncthreads();
874	        // ff2 = X_gact @ ff2_w^T (+ ff2_b) (N=d, K=dff). fp32 → work.
875	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_gact[li] + (int64_t)g0 * dec::kDff, wb.ff2_w[li],
876	                                            sc.work, dec::kDff, dec::kD, sA, sB);
877	        __syncthreads();
878	        // r2 = x1 + ff2 + ff2_b → work (fp32). x1 lives in the dedicated fp32 buffer
879	        // (no bf16 round). ff2_b folded here — matches the oracle r2 = x1 + (ff2 + ff2_b).
880	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
881	            const int r = idx / dec::kD, j = idx % dec::kD;
882	            sc.work[(int64_t)r * dec::kD + j] += sc.x1[(int64_t)r * dec::kD + j] + L.ff2_b[j];
883	        }
884	        __syncthreads();
885	        if (li + 1 < dec::kLayers) {
886	            // n2(r2) → finalin (fp32 reused) + n2 caches[li]; bf16 → X_in[li+1].
887	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
888	            for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
889	                const int r = idx / dec::kD, j = idx % dec::kD;
890	                acts.X_in[li + 1][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.finalin[(int64_t)r * dec::kD + j]);
891	            }
892	            __syncthreads();
893	        } else {
894	            // last layer: n2(r2) → finalin (fp32, all positions; head reads last pos) + n2 caches[li].
895	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
896	        }
897	    }
898	
899	    // ── Final norm + head + CE, scalar PER-SAMPLE on the LAST position only.
900	    //    finalin holds the last-layer n2 output [nrows,d] fp32. ──
901	    float nll_acc = 0.0f;
902	    for (int si = 0; si < nsamp; ++si) {
903	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
904	        const float* hlast = sc.finalin + (int64_t)rlast * dec::kD;
905	        float sum = 0.0f;
906	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += hlast[j];
907	        float mean = dec_block_sum(sum, red) / (float)dec::kD;
908	        float vs = 0.0f;
909	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) { float c = hlast[j] - mean; vs += c * c; }
910	        float var = dec_block_sum(vs, red) / (float)dec::kD;
911	        float iv = rsqrtf(var + dec::kLnEps);
912	        if (threadIdx.x == 0) sc.fni[rlast] = iv;
913	        // fn_xhat cache (last row); hn → X_hn (bf16 head dW operand) AND reuse the
914	        // X_hn bf16 as the scalar head input (read back below).
915	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
916	            float xh = (hlast[j] - mean) * iv;
917	            sc.fnx[(int64_t)rlast * dec::kD + j] = xh;
918	            float hn = xh * w.norm_w[j] + w.norm_b[j];
919	            acts.X_hn[(int64_t)si_global(g0, si) * dec::kD + j] = __float2bfloat16(hn);
920	        }
921	        __syncthreads();
922	        // logits[o] = hn · out_w[o] + out_b[o]  (scalar; hn read from X_hn bf16 so the
923	        // head input == the head dW operand exactly). Store into sc.logits[si*V..].
924	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
925	        const __nv_bfloat16* hnb = acts.X_hn + (int64_t)si_global(g0, si) * dec::kD;
926	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
927	            const float* Wr = w.out_w + (int64_t)o * dec::kD;
928	            float acc = w.out_b[o];
929	            #pragma unroll 4
930	            for (int k = 0; k < dec::kD; ++k) acc += __bfloat162float(hnb[k]) * Wr[k];
931	            lg[o] = acc;
932	        }
933	        __syncthreads();
934	        int tgt = tgt_ids[si_global(g0, si)];
935	        float lmax = -CUDART_INF_F;
936	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
937	        lmax = dec_block_max(lmax, red);
938	        float es = 0.0f;
939	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
940	        es = dec_block_sum(es, red);
941	        float logz = lmax + __logf(es);
942	        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
943	        __syncthreads();
944	    }
945	    return nll_acc;
946	}
