948	// Attention BACKWARD over a tile (the oracle's 3-pass form, tile-batched).
949	// Reads qkv (bf16), attn weights, and dctx [nrows,d] fp32; writes dqkv [nrows,3d]
950	// fp32 into `dqkv_out`. dsc is the per-CTA dscores scratch. Mirror of
951	// dec_backward_sample's attention block (A: dv, B: dscores, C: dq/dk), looped
952	// over the tile's samples. scale = 1/sqrt(dh).
953	__device__ __forceinline__ void dectc_attn_bwd_tile(
954	        const __nv_bfloat16* __restrict__ qkv, const float* __restrict__ attn_w,
955	        const float* __restrict__ dctx, int nrows,
956	        float* __restrict__ dqkv_out, float* __restrict__ dsc) {
957	    const int nsamp = nrows / dec::kSeq;
958	    const float scale = dec::attn_scale();
959	    // A: dv[kj] = Σ_{qi>=kj} attn[qi,kj] * dctx[qi].  Owner: (sample,kj,head,t).
960	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
961	        const int si  = r / (dec::kSeq * dec::kHeads * dec::kDhead);
962	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
963	        const int kj  = rem / (dec::kHeads * dec::kDhead);
964	        rem = rem % (dec::kHeads * dec::kDhead);
965	        const int hh  = rem / dec::kDhead, t = rem % dec::kDhead;
966	        const int qoff = hh * dec::kDhead;
967	        const int rbase = si * dec::kSeq;
968	        const float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
969	        float acc = 0.0f;
970	        #pragma unroll
971	        for (int qi = kj; qi < dec::kSeq; ++qi)
972	            acc += aw[qi * dec::kSeq + kj] * dctx[(int64_t)(rbase + qi) * dec::kD + qoff + t];
973	        dqkv_out[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t] = acc;   // dv block
974	    }
975	    __syncthreads();
976	    // B: dscores ds[qi,kj] = attn*(datt - Σ_k datt*attn)*scale, masked kj>qi → 0.
977	    //    datt[kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t]. Owner: (sample,head,qi).
978	    for (int r = threadIdx.x; r < nsamp * dec::kHeads * dec::kSeq; r += blockDim.x) {
979	        const int si = r / (dec::kHeads * dec::kSeq);
980	        int rem = r % (dec::kHeads * dec::kSeq);
981	        const int hh = rem / dec::kSeq, qi = rem % dec::kSeq;
982	        const int qoff = hh * dec::kDhead;
983	        const int rbase = si * dec::kSeq;
984	        const float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;
985	        float datt[dec::kSeq];
986	        #pragma unroll
987	        for (int kj = 0; kj < dec::kSeq; ++kj) {
988	            if (kj > qi) { datt[kj] = 0.0f; continue; }
989	            float acc = 0.0f;
990	            #pragma unroll
991	            for (int t = 0; t < dec::kDhead; ++t)
992	                acc += dctx[(int64_t)(rbase + qi) * dec::kD + qoff + t]
993	                     * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t]);
994	            datt[kj] = acc;
995	        }
996	        float dot = 0.0f;
997	        #pragma unroll
998	        for (int kj = 0; kj <= qi; ++kj) dot += datt[kj] * aw[qi * dec::kSeq + kj];
999	        float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq + qi) * dec::kSeq;
1000	        #pragma unroll
1001	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1002	            float a = aw[qi * dec::kSeq + kj];
1003	            ds[kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale : 0.0f;
1004	        }
1005	    }
1006	    __syncthreads();
1007	    // C: dq[qi] = Σ_kj ds[qi,kj]*k[kj]; dk[kj] = Σ_qi ds[qi,kj]*q[qi]. Owner: (sample,pos,head,t).
1008	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
1009	        const int si = r / (dec::kSeq * dec::kHeads * dec::kDhead);
1010	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
1011	        const int pos = rem / (dec::kHeads * dec::kDhead);
1012	        rem = rem % (dec::kHeads * dec::kDhead);
1013	        const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
1014	        const int qoff = hh * dec::kDhead;
1015	        const int rbase = si * dec::kSeq;
1016	        const float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
1017	        float dq = 0.0f, dk = 0.0f;
1018	        #pragma unroll
1019	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1020	            dq += ds[pos * dec::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + dec::kD + qoff + t]);
1021	            dk += ds[kj * dec::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + qoff + t]);
1022	        }
1023	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + qoff + t] = dq;             // dq block
1024	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + dec::kD + qoff + t] = dk;   // dk block
1025	    }
1026	    __syncthreads();
1027	}
