1029	// ════════════════════════════════════════════════════════════════════════
1030	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
1031	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
1032	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
1033	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
1034	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
1035	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
1036	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
1037	//
1038	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
1039	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
1040	//  is the dedicated scratch.dh.
1041	// ════════════════════════════════════════════════════════════════════════
1042	__device__ void dectc_backward_tile(
1043	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, int B, const DecActs& acts,
1044	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
1045	        float* __restrict__ lnvec, float* __restrict__ work2,
1046	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
1047	    const int nsamp = nrows / dec::kSeq;
1048	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
1049	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
1050	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
1051	    for (int li = 0; li < dec::kLayers; ++li) {
1052	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
1053	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
1054	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
1055	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
1056	    }
1057	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
1058	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
1059	
1060	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
1061	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
1062	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
1063	    // First zero scratch.dh for the whole tile (only last positions get grad).
1064	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
1065	    __syncthreads();
1066	    for (int si = 0; si < nsamp; ++si) {
1067	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
1068	        const int gs = si_global(g0, si);
1069	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
1070	        int tgt = tgt_ids[gs];
1071	        // softmax of cached logits.
1072	        float lmax = -CUDART_INF_F;
1073	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
1074	        lmax = dec_block_max(lmax, red);
1075	        float es = 0.0f;
1076	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1077	        es = dec_block_sum(es, red);
1078	        float inv_es = 1.0f / es;
1079	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
1080	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
1081	            float smo = __expf(lg[o] - lmax) * inv_es;
1082	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
1083	            lg[o] = dl;
1084	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
1085	        }
1086	        __syncthreads();
1087	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
1088	        // Then final-norm bwd of that single row → scratch.dh[rlast].
1089	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
1090	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1091	            float dhn = 0.0f;
1092	            for (int o = 0; o < dec::kVocab; ++o)
1093	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
1094	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
1095	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
1096	        }
1097	        __syncthreads();
1098	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
1099	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1100	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
1101	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
1102	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
1103	        }
1104	        __syncthreads();
1105	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
1106	        {
1107	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
1108	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
1109	            float sda = 0.0f, sdax = 0.0f;
1110	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1111	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
1112	            }
1113	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
1114	            float iv = sc.fni[rlast];
1115	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1116	                float dxhat = dyr[j] * w.norm_w[j];
1117	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
1118	            }
1119	            __syncthreads();
1120	        }
1121	    }
1122	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
1123	
1124	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
1125	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
1126	    //    recompute). ──
1127	    for (int li = dec::kLayers - 1; li >= 0; --li) {
1128	        const DecWeights::Layer& L = w.layer[li];
1129	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
1130	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
1131	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 acts (bf16).
1132	        // dx1 starts as dr2 (copy into work2), the FFN path adds to it.
1133	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1134	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
1135	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
1136	        }
1137	        __syncthreads();
1138	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → tw? need a [nrows,dff] buffer.
1139	        //   Use sc.work (currently dr2, no longer needed — dx1 saved in work2, dff2 in acts).
1140	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, wb.ff2_w[li],
1141	                                           sc.work, dec::kDff, dec::kD, sA, sB);  // dgact [nrows,dff]
1142	        __syncthreads();
1143	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 acts (bf16) AND keep fp32 in sc.work for dX.
1144	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1145	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
1146	            sc.work[idx] = dff0;
1147	            acts.dY_ff0[li][(int64_t)g0 * dec::kDff + idx] = __float2bfloat16(dff0);
1148	        }
1149	        __syncthreads();
1150	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
1151	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
1152	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, wb.ff0_w[li],
1153	                                           sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB);  // dx1_ffn [nrows,d]
1154	        __syncthreads();
1155	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1156	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
1157	        __syncthreads();
1158	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β. xhat=n1x[li], inv=n1i[li].
1159	        dectc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
1160	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
1161	        // SAVE the residual dr1 into sc.dh NOW (dh is free — its grad was consumed into
1162	        // dr2 at the top of this layer); attention bwd will overwrite work2. Then add the
1163	        // in_proj dX path to it. da → dY_a acts (bf16, out_proj dW operand).
1164	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1165	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1  (saved across attn bwd)
1166	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
1167	        }
1168	        __syncthreads();
1169	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
1170	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, wb.out_w[li],
1171	                                           sc.work, dec::kD, dec::kD, sA, sB);  // dctx
1172	        __syncthreads();
1173	        // attention bwd: (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d] fp32 into
1174	        //   work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv acts (bf16, in_proj dW operand).
1175	        dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
1176	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x)
1177	            acts.dY_qkv[li][(int64_t)g0 * 3 * dec::kD + idx] = __float2bfloat16(work2[idx]);
1178	        __syncthreads();
1179	        // in_proj dX: dx_in_attn = dqkv @ in_w  (output width Kin=d, contract Nout=3d).
1180	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
1181	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * dec::kD, wb.in_w[li],
1182	                                           sc.work, /*Kin=*/dec::kD, /*Nout=*/3 * dec::kD, sA, sB);  // dx_in_attn
1183	        __syncthreads();
1184	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1185	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
1186	        __syncthreads();
1187	    }
1188	
1189	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 acts (bf16); the
1190	    //    tok/pos owner-scan (P2) reads dh0 by global token row. ──
1191	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1192	        acts.dh0[(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.dh[idx]);
1193	    __syncthreads();
1194	}
