1197	//  SAM-cell-scoped OUT-OF-LINE tile shims (reg-pressure campaign C2 -- the
1198	//  mamba precedent, model_stage_mamba_tc.cuh mbtc_forward_tile/backward_tile,
1199	//  SCOPED).  The SAM-coupled cells (LookSAM/SG11/SG15/SG2) run the heavy tile
1200	//  fwd+bwd TWICE per step (P1 + the P2.4 SAM 2nd pass); inlining both copies
1201	//  into one kernel blows the 255-reg budget by ~15 KB of hot-loop spills.
1202	//  Routing BOTH passes of those cells through these __noinline__ shims gives
1203	//  one shared out-of-line frame (measured: total spill bytes roughly halve and
1204	//  leave the entry body nearly clean).  The single-pass cells keep calling the
1205	//  inline bodies directly -- their allocation (255 regs, ZERO spills) is
1206	//  byte-identical to the pre-campaign engine, never taxed with an ABI boundary.
1207	//  Math identical; warpgroup-uniform call (whole CTA enters/exits together) so
1208	//  the wgmma fence/commit/wait choreography inside is well-formed.
1209	// ════════════════════════════════════════════════════════════════════════
1210	__device__ __noinline__ float dectc_forward_tile_outlined(
1211	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, const DecActs& acts,
1212	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
1213	        const int* __restrict__ tgt_ids,
1214	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
1215	    return dectc_forward_tile(w, wb, g0, nrows, acts, sc, tok_ids, tgt_ids, sA, sB, red);
1216	}
1217	__device__ __noinline__ void dectc_backward_tile_outlined(
1218	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, int B, const DecActs& acts,
1219	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
1220	        float* __restrict__ lnvec, float* __restrict__ work2,
1221	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
1222	    dectc_backward_tile(w, wb, g0, nrows, B, acts, sc, tgt_ids, lnvec, work2, sA, sB, red);
1223	}
