1225	// ════════════════════════════════════════════════════════════════════════
1226	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
1227	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
1228	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
1229	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
1230	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
1231	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
1232	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
1233	//
1234	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
1235	//  the contraction length K (T for per-position weights, B for the head).
1236	// ════════════════════════════════════════════════════════════════════════
1237	struct DecDwSpec {
1238	    const __nv_bfloat16* dY;   // [K, Nout]
1239	    const __nv_bfloat16* X;    // [K, Kin]
1240	    int Nout; int Kin; int K;
1241	    int grad_off;              // element offset of this weight in `grad`
1242	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
1243	    int bias_off;              // element offset of the bias in `grad`
1244	};
1245	
1246	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
1247	__device__ __forceinline__ void dectc_build_dw_specs(
1248	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
1249	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
1250	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
1251	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
1252	    //   head: out_w=28 (out_b=29)
1253	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
1254	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
1255	    for (int s = 0; s < 8; ++s) {
1256	        const int li = s / 4, kind = s % 4;

1257	        DecDwSpec& sp = spec[s];
1258	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
1259	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
1260	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
1261	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
1262	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
1263	        sp.dY_bias = sp.dY;
1264	    }
1265	    DecDwSpec& hd = spec[8];
1266	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
1267	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
1268	}
1269	
1270	// ── dW M-atom INTERLEAVE group width (task #13 H3). A dW output "tile" (work
1271	//    item) owns a GROUP of up to kDecDwIL consecutive m64 atoms instead of one,
1272	//    so the engine runs kDecDwIL wgmmas/k-step into independent fragments sharing
1273	//    ONE staged X (B-operand) tile → the H1 win (overlap the MMAs + kDecDwIL× less
1274	//    X-operand HBM traffic) now applies to the dW K=T contraction (the post-H2
1275	//    dominant phase). kDecDwIL == the engine's interleave cap kDecMaxIL so the
1276	//    ring smem (DecTcSmem.sA, sized kDecAtomsPerSlot=min(kAtomsM,kDecMaxIL) A-tiles
1277	//    per slot) and the selftest-validated dW path (gemm_dw_kernel: MaxAtomsM=8,
1278	//    kIL=min(8,2)=2) match exactly. Ascending-k per atom is unchanged → numerics
1279	//    bit-identical + A/A/A determinism. Atoms-per-weight-N-tile / groups: ──
1280	constexpr int kDecDwIL = kDecMaxIL;
1281	__device__ __host__ __forceinline__ int dec_dw_atoms(int Nout)  { return (Nout + 63) / 64; }
1282	__device__ __host__ __forceinline__ int dec_dw_groups(int Nout) {
1283	    return (dec_dw_atoms(Nout) + kDecDwIL - 1) / kDecDwIL;
1284	}
1285	
1286	// Total number of dW output WORK ITEMS (M-atom groups × N-tiles) across the 9
1287	// weights (the tile loop count). Each item is a group of <= kDecDwIL m64 atoms.
1288	template <int N>
1289	__device__ __forceinline__ int dectc_dw_total_tiles(const DecDwSpec spec[9]) {
1290	    int n = 0;
1291	    for (int s = 0; s < 9; ++s)
1292	        n += dec_dw_groups(spec[s].Nout) * ((spec[s].Kin + N - 1) / N);
1293	    return n;
1294	}
1295	
1296	// Run ONE global dW work item `gt` (if it belongs to this CTA): decode (weight,
1297	// M-atom GROUP, N-tile), then contract K via the dW GEMM into grad[grad_off]. The
1298	// group is up to kDecDwIL stacked m64 atoms → the engine interleaves them (kIL=
1299	// kDecDwIL): kDecDwIL wgmmas/k-step into independent fragments sharing ONE staged
1300	// X B-tile (H1's win, now on the dW K=T contraction).
1301	template <int N>
1302	__device__ __forceinline__ void dectc_dw_run_tile(
1303	        const DecDwSpec spec[9], int gt, float* __restrict__ grad,
1304	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1305	    // Decode gt → (s, m_group, n_tile).
1306	    int acc = 0, s = 0, m_group = 0, n_tile = 0;
1307	    for (s = 0; s < 9; ++s) {
1308	        const int ng = dec_dw_groups(spec[s].Nout);
1309	        const int nt = (spec[s].Kin + N - 1) / N;
1310	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; break; }
1311	        acc += ng * nt;
1312	    }
1313	    const DecDwSpec& sp = spec[s];
1314	    const int n_atoms = dec_dw_atoms(sp.Nout);
1315	    const int a0 = m_group * kDecDwIL;               // first atom of the group
1316	    const int g_atoms = (n_atoms - a0) < kDecDwIL ? (n_atoms - a0) : kDecDwIL;
1317	    const int mbase = a0 * 64;
1318	    const int n0 = n_tile * N;
1319	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1320	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1321	    const int Nout = sp.Nout, Kin = sp.Kin;
1322	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1323	    // The engine (tc_gemm_block_unpipelined, mbase0=mbase) passes the GLOBAL row
1324	    // m = mbase + (group-local row) to srcA/out (it adds mbase0 itself), so the
1325	    // accessors use `m` RAW — adding mbase again would double-count (the selftest
1326	    // gemm_dw_kernel passes mbase0=0, m_atoms=all, and uses m raw; we shard the
1327	    // atoms into groups, pass mbase0=mbase, and likewise use m raw).
1328	    // A[m=out, k=t] = dY[t,out]  (transposed read); B[n=in, k=t] = X[t,in] (transposed).
1329	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1330	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1331	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1332	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1333	    auto out  = [&] (int m, int n, float v) {
1334	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1335	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kDecDwIL>(
1336	        mbase, g_atoms, n_real, k_steps, srcA, srcB, out, sA, sB);
1337	}
