1339	// ════════════════════════════════════════════════════════════════════════
1340	//  SPLIT-K dW (multi-CTA tiling — the validated mamba fix). The 9 dW yield only
1341	//  ~50 output tiles → ~62% of 132 SMs idle in P2. Split-K turns each output tile
1342	//  into G work items (one per K-chunk), so the grid sees (n_dw·G) items → idle
1343	//  SMs do work. Each CTA computes a PARTIAL over its K-chunk into a per-(tile,
1344	//  chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-chunk
1345	//  reduce sums the G partials into grad — no float atomics, fixed order, so
1346	//  parity + A/A/A bit-determinism hold (each partial is the SAME ascending-k fp32
1347	//  wgmma accumulate; Σ_chunk == full-K sum reassociated into G fp32 blocks).
1348	//  G==1 routes to the single-CTA dectc_dw_run_tile above (no scratch). Slot (gt,
1349	//  kc) at dw_part[((gt*G+kc)) * (kDecDwIL·64·kDecMaxTileN) + lr*kDecMaxTileN + col]
1350	//  — each work item gt is an M-atom GROUP (up to kDecDwIL=2 stacked m64 atoms, H3),
1351	//  so its slot holds kDecDwIL·64 group-local rows (lr). Decoder K varies per spec:
1352	//  layer dW K=T, head dW K=B (so kc_steps reads sp.K).
1353	// ════════════════════════════════════════════════════════════════════════
1354	constexpr int kDecMaxTileN = SG_TUNED_TILE_N;                       // widest dW N-tile
1355	// Floats per (gt,kc) split-K slot: a work item is an M-atom GROUP of up to kDecDwIL
1356	// stacked m64 atoms → kDecDwIL·64 rows × N cols. (Was 64·N for the 1-atom item.)
1357	constexpr int kDecDwTileFloats = kDecDwIL * wgs::kWgmmaAtomM * kDecMaxTileN;
1358	
1359	// COMPILE-TIME max #dW output WORK ITEMS (the 9 dW have fixed Nout/Kin; decoder
1360	// dims are compile-time → constant). per layer: qkv(3d×d), attn_out(d×d), ff0(dff
1361	// ×d), ff2(d×dff), N=kDecMaxTileN; + head(V×d). The M factor is now M-atom GROUPS
1362	// of kDecDwIL (ceil(atoms/kDecDwIL)), matching dec_dw_groups — NOT single atoms.
1363	constexpr int kDecDwMGroups(int Nout) {                 // ceil(ceil(Nout/64)/kDecDwIL)
1364	    return (((Nout + 63) / 64) + kDecDwIL - 1) / kDecDwIL;
1365	}
1366	constexpr int kDecDwTilesPerLayer =
1367	      kDecDwMGroups(3*dec::kD) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // qkv
1368	    + kDecDwMGroups(dec::kD)   * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // attn_out
1369	    + kDecDwMGroups(dec::kDff) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // ff0
1370	    + kDecDwMGroups(dec::kD)   * ((dec::kDff+ kDecMaxTileN - 1)/kDecMaxTileN);  // ff2
1371	constexpr int kDecDwHeadTiles =
1372	      kDecDwMGroups(dec::kVocab) * ((dec::kD + kDecMaxTileN - 1)/kDecMaxTileN);
1373	constexpr int kDecDwMaxTiles = dec::kLayers * kDecDwTilesPerLayer + kDecDwHeadTiles;
1374	
1375	// Split-K dW partial-scratch float count (host carves it from the workspace tail).
1376	__host__ __device__ __forceinline__ int64_t dec_dw_part_floats(int G) {
1377	    return (int64_t)kDecDwMaxTiles * G * kDecDwTileFloats;
1378	}
1379	
1380	// Decode global dW work-item index gt → (spec index s, m_group, n_tile). Single-
1381	// source: m_group indexes M-atom GROUPS of kDecDwIL (group's first atom = m_group·
1382	// kDecDwIL, base row = m_group·kDecDwIL·64).
1383	template <int N>
1384	__device__ __forceinline__ void dectc_dw_decode(
1385	        const DecDwSpec spec[9], int gt, int& s, int& m_group, int& n_tile) {
1386	    int acc = 0;
1387	    for (s = 0; s < 9; ++s) {
1388	        const int ng = dec_dw_groups(spec[s].Nout);
1389	        const int nt = (spec[s].Kin + N - 1) / N;
1390	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; return; }
1391	        acc += ng * nt;
1392	    }
1393	    s = 8; m_group = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
1394	}
1395	
1396	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk uses sp.K
1397	// (layer T / head B). FLOOR-BALANCED partition: chunk kc = [k0,k1) with
1398	// k0=floor(kc·KS/G), k1=floor((kc+1)·KS/G) — near-equal, summing to KS EXACTLY for
1399	// ANY KS≥G (no `G | KS` requirement → works at the production truncated B=4176,
1400	// where the head's KS=B/16 need NOT be divisible by G). A CEIL split would leave a
1401	// trailing EMPTY chunk whose slot stays unwritten → the reduce sums garbage (the
1402	// determinism-blind dW bug); floor never empties a chunk for KS≥G. Fresh ScaleD=0
1403	// per chunk → true partial. Writes the full 64×N tile (LOCAL rows) to the slot.
1404	template <int N>
1405	__device__ __forceinline__ void dectc_dw_run_tile_splitk(
1406	        const DecDwSpec spec[9], int gt, int kc, int G, float* __restrict__ dw_part,
1407	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1408	    int s, m_group, n_tile;
1409	    dectc_dw_decode<N>(spec, gt, s, m_group, n_tile);
1410	    const DecDwSpec& sp = spec[s];
1411	    const int n_atoms = dec_dw_atoms(sp.Nout);
1412	    const int a0 = m_group * kDecDwIL;                      // first atom of the group
1413	    const int g_atoms = (n_atoms - a0) < kDecDwIL ? (n_atoms - a0) : kDecDwIL;
1414	    const int mbase = a0 * 64;
1415	    const int n0 = n_tile * N;
1416	    const int KS = sp.K / wgs::kWgmmaAtomK;                 // total k-atoms (T/16 or B/16)
1417	    const int k0 = (int)(((int64_t)kc       * KS) / G);     // floor-balanced chunk bounds
1418	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
1419	    const int kc_steps = k1 - k0;                          // sums to KS exactly over kc
1420	    // Slot holds the GROUP's kDecDwIL·64 rows (lr) × N cols (kDecDwTileFloats).
1421	    float* slot = dw_part + ((int64_t)gt * G + kc) * kDecDwTileFloats;
1422	    // Empty-chunk guard (KS<G, i.e. B<64): a k_steps=0 GEMM would emit the
1423	    // uninitialized accumulator → zero the WHOLE group slot + return instead of
1424	    // running it (the reduce sums all G slots unconditionally, so an empty chunk
1425	    // MUST be 0). Zero the full kDecDwIL·64·N slot (only g_atoms·64 rows are valid
1426	    // but the reduce reads only valid rows; zeroing all keeps it simple + safe).
1427	    if (kc_steps <= 0) {
1428	        for (int i = threadIdx.x; i < kDecDwTileFloats; i += blockDim.x) slot[i] = 0.0f;
1429	        __syncthreads();
1430	        return;
1431	    }
1432	    const int Nout = sp.Nout, Kin = sp.Kin;
1433	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1434	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1435	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1436	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1437	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1438	    // out(mbase+row, col, v): m is GLOBAL (srcA needs it; engine adds mbase0=mbase);
1439	    // the slot holds the GROUP's kDecDwIL·64 LOCAL rows → index by (m - mbase). The
1440	    // engine emits group-local rows in [0, g_atoms·64); writing them by (m-mbase)
1441	    // fills the lower g_atoms·64 rows (a ragged final group's tail rows stay as the
1442	    // zeroed/garbage upper rows but the reduce reads only valid rows → never used).
1443	    auto out  = [&] (int m, int n, float v) {
1444	        const int lr = m - mbase;
1445	        if (lr >= 0 && lr < kDecDwIL * 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1446	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kDecDwIL>(
1447	        mbase, g_atoms, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1448	}
1449	
1450	// Deterministic reduce: output tile gt (% nCTA) sums its G chunk-partials ascending-kc
1451	// → grad. Same (gt → geometry) decode as the partial.
1452	template <int N>
1453	__device__ __forceinline__ void dectc_dw_reduce_splitk(
1454	        const DecDwSpec spec[9], int n_dw, int G, const float* __restrict__ dw_part,
1455	        float* __restrict__ grad, int cta, int nCTA) {
1456	    for (int gt = cta; gt < n_dw; gt += nCTA) {
1457	        int s, m_group, n_tile;
1458	        dectc_dw_decode<N>(spec, gt, s, m_group, n_tile);
1459	        const DecDwSpec& sp = spec[s];
1460	        const int mbase = m_group * kDecDwIL * 64;          // group's first global row
1461	        const int n0 = n_tile * N;
1462	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1463	        // Valid group rows: up to kDecDwIL·64, clamped to the weight's row count.
1464	        const int grp_rows = kDecDwIL * 64;
1465	        const int Nrow = (sp.Nout - mbase) < grp_rows ? (sp.Nout - mbase) : grp_rows;
1466	        const int64_t base = (int64_t)gt * G * kDecDwTileFloats;
1467	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
1468	            const int row = idx / n_real, col = idx % n_real;   // row = group-local lr
1469	            float accv = 0.0f;
1470	            for (int kc = 0; kc < G; ++kc)
1471	                accv += dw_part[base + (int64_t)kc * kDecDwTileFloats + (int64_t)row * N + col];
1472	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
1473	        }
1474	    }
1475	}
