1477	// Biases db = Σ_K dY  (column-sum of dY[K,Nout] → [Nout], per output row).
1478	//
1479	// WAS: each CTA strided ALL bias outputs and ran the full Σ_K reduction — i.e. the
1480	// ENTIRE column-sum was recomputed redundantly on ALL ~132 CTAs (the comment called
1481	// it "cheap" — true only when Nout≤3d=384 at the d=128 production width; at the
1482	// d=1024 roofline width Nout reaches 4d=4096 and K=T=65536, so the 132× redundant
1483	// reduction was the DOMINANT grad_asm cost — ~500 ms, eclipsing even the embedding
1484	// scan this task set out to fix; the per-phase profiler (ga.biases sub-timer) made
1485	// it visible). HBM traffic was 132 × Σ_s K_s·Nout_s·2 B ≈ 70 GB.
1486	//
1487	// NOW: SINGLE OWNER per output element across the WHOLE grid. Flatten the 9 specs'
1488	// outputs into one global index space [0, ΣNout) and grid-stride it over all CTAs
1489	// × threads, so each bias output is reduced EXACTLY ONCE and the work is spread
1490	// across the full grid. Traffic collapses to Σ_s K_s·Nout_s·2 B (one pass, ≈ 130×
1491	// less at d=1024). Reads stay COALESCED (consecutive threads → consecutive o on the
1492	// same k → consecutive dY addresses). DETERMINISM: one owner per output + the SAME
1493	// ascending-k fp32 accumulation → bit-identical to the old per-output sum, no atomics.
1494	//
1495	// PORTABLE: the "single-owner grid-stride column-sum" is the general fix for any
1496	// bias/reduction-to-a-vector that a megakernel was recomputing per-CTA; vit/mamba
1497	// bias grads (same db = Σ_K dY shape) reuse this verbatim.
1498	__device__ __forceinline__ void dectc_dw_biases(
1499	        const DecDwSpec spec[9], float* __restrict__ grad, int cta, int nCTA) {
1500	    // exclusive prefix of Nout across the 9 specs → total bias-output count.
1501	    int pre[10];
1502	    pre[0] = 0;
1503	    #pragma unroll
1504	    for (int s = 0; s < 9; ++s) pre[s + 1] = pre[s] + spec[s].Nout;
1505	    const int total = pre[9];
1506	    const int stride = nCTA * blockDim.x;
1507	    for (int go = cta * blockDim.x + threadIdx.x; go < total; go += stride) {
1508	        // decode global output index → (spec s, local row o). 9 specs → linear scan.
1509	        int s = 0;
1510	        #pragma unroll
1511	        for (int t = 0; t < 9; ++t) if (go >= pre[t + 1]) s = t + 1;
1512	        const DecDwSpec& sp = spec[s];
1513	        const int o = go - pre[s];
1514	        float accv = 0.0f;
1515	        for (int k = 0; k < sp.K; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
1516	        grad[sp.bias_off + o] = accv;
1517	    }
1518	}
