1520	// ════════════════════════════════════════════════════════════════════════
1521	//  P2 — EMBEDDING grad (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1522	//
1523	//  WAS (the owner-LINEAR-SCAN, task #13 H2 target): each of V owner-CTAs scanned
1524	//  ALL T tokens (`if tok_ids[t]==r` per token), re-reading the WHOLE dh0 stream V
1525	//  times — O(V·d·T) work + V passes over 134 MB of dh0, where O(d·T) (ONE pass)
1526	//  suffices. V=99<132 left 33 CTAs idle; threads beyond d idled per owner; pos
1527	//  used only S=4 owner-CTAs scanning all T with a t%S branch.
1528	//
1529	//  NOW (H2 — counting-sort token lists + flat-element grid-stride):
1530	//    BUILD (dectc_embed_build_lists, once, cta 0, in the P1 window so it overlaps
1531	//    fwd/bwd and adds NO barrier — B1 already fences it before P2 consumes):
1532	//    a deterministic integer counting sort over tok_ids → row_start[V+1] (CSR
1533	//    offsets) + perm[T] (token positions bucketed by vocab row, ASCENDING t
1534	//    within each row, because the scatter visits t ascending and appends).
1535	//    CONSUME (dectc_embed_owner_scan): a flat grid-stride over ALL V·d output
1536	//    elements. Element (r,j) walks ONLY row r's own tokens perm[row_start[r] ..
1537	//    row_start[r+1]) in ascending-t order, reading dh0[perm[i]·d + j]. Total
1538	//    work collapses to O(d·T) (each dh0 value read once in aggregate); reads are
1539	//    COALESCED (consecutive threads = consecutive j on the same token row); ALL
1540	//    132 CTAs + full blockDim are busy (V·d=101376 elems ≫ 132·256). pos is the
1541	//    same flat grid-stride but needs NO list: tokens with (t%S)==p are exactly
1542	//    t = p, p+S, …, p+(B-1)·S (T=B·S), a closed-form ascending walk of length B.
1543	//
1544	//  DETERMINISM: per row the accumulation order over its tokens is the SAME fixed
1545	//  ascending-t order as the old scan (perm is built ascending; pos walk is
1546	//  ascending) → bitwise-identical fp32 accumulation, no float atomics, no timing-
1547	//  dependent order. The build is integer-exact (histogram counts + prefix +
1548	//  serial ascending scatter), so row_start/perm are bit-identical every rerun.
1549	//
1550	//  PORTABLE: this CSR-bucket + flat-element grid-stride is the general pattern for
1551	//  any "gather grad into a small set of embedding/lookup rows" — vit patch-proj /
1552	//  pos-embed rows and mamba's embedding will reuse dectc_embed_build_lists +
1553	//  this consume verbatim (only the row count V and the membership map differ; a
1554	//  structural map like pos needs no list at all).
1555	// ════════════════════════════════════════════════════════════════════════
1556	
1557	// Scratch float count for the embedding token lists (host carves it from the
1558	// workspace tail). row_start[V+1] + perm[T], stored as int32 (1 float slot each).
1559	__host__ __device__ __forceinline__ int64_t dec_embed_lists_floats(int T) {
1560	    return (int64_t)(dec::kVocab + 1) + (int64_t)T;
1561	}
1562	
1563	// BUILD the per-vocab-row token lists (counting sort). Single CTA (caller guards
1564	// cta==0); runs in the P1 window so it overlaps fwd/bwd and the existing B1
1565	// barrier fences it before the P2 consume — NO new barrier. `row_start` is
1566	// [V+1] int32 (CSR offsets), `perm` is [T] int32 (token positions, ascending t
1567	// within each vocab-row bucket). All integer ops → bit-exact + deterministic.
1568	//
1569	// COST: O(T), PARALLEL over kW worker lanes (HBM-latency hidden) so the build is a
1570	// few hundred µs — far below the consume saving it enables. DETERMINISM via a fixed
1571	// STRUCTURAL decomposition: worker w owns the CONTIGUOUS t-chunk [w·C,(w+1)·C); it
1572	// histograms then scatters its chunk in ascending t into a per-(worker,row) slice
1573	// of perm whose base sits AFTER all lower-w workers' slices for the same row. Lower
1574	// w ⇒ lower t, and within a worker ascending t ⇒ each row's perm bucket is GLOBALLY
1575	// ascending t — the SAME order the old single-cursor scatter (and the old owner-scan
1576	// accumulation) produced, so bit-identical. All integer ops; no atomics on the hot
1577	// path. tok_ids is HBM int32 [T]. row_start is [V+1] (CSR offsets); perm is [T].
1578	__device__ __forceinline__ void dectc_embed_build_lists(
1579	        const int* __restrict__ tok_ids, int T,
1580	        int* __restrict__ row_start, int* __restrict__ perm) {
1581	    constexpr int kW = 64;                         // worker lanes (latency hiding)
1582	    __shared__ int wcnt[kW * dec::kVocab];         // per-(worker,row) count, then base cursor
1583	    // floor-balanced contiguous t-chunk per worker w: [c0(w), c0(w+1)).
1584	    auto c0 = [&] (int w) -> int { return (int)(((int64_t)w * T) / kW); };
1585	    // 1) zero the per-worker histograms (all threads).
1586	    for (int i = threadIdx.x; i < kW * dec::kVocab; i += blockDim.x) wcnt[i] = 0;
1587	    __syncthreads();
1588	    // 2) each of the first kW threads histograms its contiguous t-chunk into its own
1589	    //    row of wcnt (no atomics — private per worker).
1590	    if (threadIdx.x < kW) {
1591	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
1592	        int* my = wcnt + (int64_t)w * dec::kVocab;
1593	        for (int t = e0; t < e1; ++t) {
1594	            const int r = tok_ids[t];
1595	            if (r >= 0 && r < dec::kVocab) my[r]++;
1596	        }
1597	    }
1598	    __syncthreads();
1599	    // 3) exclusive prefix over r → row_start[V+1] (single thread; V tiny). totals[r]
1600	    //    = Σ_w wcnt[w][r]. row_start is exclusive over rows (CSR).
1601	    if (threadIdx.x == 0) {
1602	        int acc = 0;
1603	        for (int r = 0; r < dec::kVocab; ++r) {
1604	            row_start[r] = acc;
1605	            for (int w = 0; w < kW; ++w) acc += wcnt[(int64_t)w * dec::kVocab + r];
1606	        }
1607	        row_start[dec::kVocab] = acc;   // == #tokens with a valid row (≤ T)
1608	    }
1609	    __syncthreads();
1610	    // 4) per-(worker,row) base cursor: wcnt[w][r] ← row_start[r] + Σ_{w'<w} cnt[w'][r]
1611	    //    (ascending-worker prefix WITHIN a row → lower-t chunks land first). One
1612	    //    thread per row (V≤256 → fits blockDim) scans workers ascending.
1613	    if (threadIdx.x < dec::kVocab) {
1614	        const int r = threadIdx.x;
1615	        int base = row_start[r];
1616	        for (int w = 0; w < kW; ++w) {
1617	            int* slot = &wcnt[(int64_t)w * dec::kVocab + r];
1618	            const int c = *slot;
1619	            *slot = base;        // becomes the live append cursor for (w,r)
1620	            base += c;
1621	        }
1622	    }
1623	    __syncthreads();
1624	    // 5) scatter: each worker walks its chunk ascending t, appending t to perm at
1625	    //    its per-row cursor. Ascending t within the chunk + ascending-worker bases
1626	    //    ⇒ globally ascending t per row bucket.
1627	    if (threadIdx.x < kW) {
1628	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
1629	        int* cur = wcnt + (int64_t)w * dec::kVocab;
1630	        for (int t = e0; t < e1; ++t) {
1631	            const int r = tok_ids[t];
1632	            if (r >= 0 && r < dec::kVocab) perm[cur[r]++] = t;
1633	        }
1634	    }
1635	    __syncthreads();
1636	}
