1638	// CONSUME: assemble tok + pos embedding grads from the prebuilt lists. Flat grid-
1639	// stride over V·d (tok) and S·d (pos) output elements → all CTAs + threads busy,
1640	// coalesced dh0 reads, fixed ascending-t accumulation per row (deterministic).
1641	__device__ __forceinline__ void dectc_embed_owner_scan(
1642	        const DecActs& acts, const int* __restrict__ row_start,
1643	        const int* __restrict__ perm, int T,
1644	        float* __restrict__ grad, int cta, int nCTA) {
1645	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
1646	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
1647	    const __nv_bfloat16* __restrict__ dh0 = acts.dh0;
1648	    const int stride = nCTA * blockDim.x;
1649	    const int base   = cta * blockDim.x + threadIdx.x;
1650	    // ── tok grad: element (r,j) over V·d, grid-strided. Walk ONLY row r's tokens
1651	    //    (perm[row_start[r] .. row_start[r+1])) ascending → coalesced dh0 column
1652	    //    read across the warp (consecutive j on one token row). ──
1653	    const int64_t Vd = (int64_t)dec::kVocab * dec::kD;
1654	    for (int64_t e = base; e < Vd; e += stride) {
1655	        const int r = (int)(e / dec::kD);
1656	        const int j = (int)(e - (int64_t)r * dec::kD);
1657	        const int s0 = row_start[r], s1 = row_start[r + 1];
1658	        float accv = 0.0f;
1659	        for (int i = s0; i < s1; ++i)
1660	            accv += __bfloat162float(dh0[(int64_t)perm[i] * dec::kD + j]);
1661	        grad[tok_off + e] = accv;
1662	    }
1663	    // ── pos grad: element (p,j) over S·d, grid-strided. Tokens with (t%S)==p are
1664	    //    t = p, p+S, …, p+(B-1)·S (T=B·S) — closed-form ascending walk, no list. ──
1665	    const int64_t Sd = (int64_t)dec::kSeq * dec::kD;
1666	    const int B = T / dec::kSeq;
1667	    for (int64_t e = base; e < Sd; e += stride) {
1668	        const int p = (int)(e / dec::kD);
